const schemaURL = computed(() => channel.value === 'vids' ? '/providers/vids/openapi.json' : channel.value === 'sku' ? '/compat/v1/openapi.json' : '/v1/openapi.json')
const swaggerURL = computed(() => channel.value === 'vids' ? '/providers/vids/api-docs' : channel.value === 'sku' ? '/compat/api-docs' : '/api-docs')
const modelCatalog = computed(() => (channel.value === 'sku' ? skuModels : channel.value === 'vids' ? [{ id: 'vids-image', type: 'image', description: 'Gemini 图片 · 文生 / 编辑' }, { id: 'vids-video', type: 'video', description: 'Omni 视频 · 六种模式' }, { id: 'vids-speech', type: 'speech', description: '语音合成 · 30 个声线' }] : flowModels).filter(item => (modelType.value === 'all' || item.type === modelType.value) && `${item.id} ${item.description || ''} ${item.displayName || ''}`.toLowerCase().includes(modelQuery.value.toLowerCase())))
const responseText = computed(() => typeof current.value.response === 'string' ? current.value.response : JSON.stringify(current.value.response, null, 2))
const requestCode = computed(() => codeFor(current.value, language.value))
watch(channel, () => { if (!endpoints[channel.value].some(item => item.id === selected.value)) selected.value = 'models'; query.value = ''; modelType.value = 'all' })
watch(() => route.query.platform, value => { channel.value = value === 'vids' ? 'vids' : 'flow' })
watch(query, () => { if (visibleEndpoints.value.length && !visibleEndpoints.value.some(item => item.id === selected.value)) selected.value = visibleEndpoints.value[0].id })
function pythonJSON(value) { return JSON.stringify(value, null, 2).replace(/"(?:\\.|[^"\\])*"|\b(?:true|false|null)\b/g, token => token === 'true' ? 'True' : token === 'false' ? 'False' : token === 'null' ? 'None' : token) }
function codeFor(entry, lang) {
  const url = origin + entry.path, headers = { Authorization: 'Bearer YOUR_API_KEY', ...(entry.idempotent ? { 'Idempotency-Key': 'my-creation-001' } : {}) }
  const body = entry.body, fileFields = Object.entries(body || {}).filter(([, value]) => typeof value === 'string' && value.startsWith('@'))
  const dataFields = Object.entries(body || {}).filter(([, value]) => !(typeof value === 'string' && value.startsWith('@')) && value !== undefined)
  if (lang === 'json') return body ? JSON.stringify(body, null, 2) : `${entry.method} ${entry.path}\nAuthorization: Bearer YOUR_API_KEY`
  if (lang === 'curl') {
    const lines = [`curl '${url}'`, ...(entry.method !== 'GET' && entry.method !== 'POST' ? [`  -X ${entry.method}`] : entry.method === 'POST' && !body ? ['  -X POST'] : []), ...Object.entries(headers).map(([key, value]) => `  -H '${key}: ${value}'`)]
    if (entry.multipart) for (const [key, value] of Object.entries(body)) lines.push(`  -F '${`${key}=${typeof value === 'object' ? JSON.stringify(value) : value}`.replaceAll("'", "'\\''")}'`)
    else if (body) lines.push("  -H 'Content-Type: application/json'", `  --data-raw '${JSON.stringify(body).replaceAll("'", "'\\''")}'`)
    if (entry.binary) lines.push(`  --output ${entry.download}`)
    return lines.join(' \\\n')
  }
  if (lang === 'python') {
    const lines = ['import os', 'import requests', '', `url = ${JSON.stringify(url)}`, 'headers = {"Authorization": f"Bearer {os.environ[\'LAY4FLOW_API_KEY\']}"}']
    if (entry.idempotent) lines.push('headers["Idempotency-Key"] = "my-creation-001"')
    if (entry.multipart) { lines.push(`data = ${pythonJSON(Object.fromEntries(dataFields.map(([key, value]) => [key, typeof value === 'object' ? JSON.stringify(value) : String(value)])))}`); fileFields.forEach(([key, value], index) => lines.push(`${'    '.repeat(index)}with open(${JSON.stringify(value.slice(1))}, "rb") as file_${index}:`)); lines.push(`${'    '.repeat(fileFields.length)}response = requests.${entry.method.toLowerCase()}(url, headers=headers, data=data,`, `${'    '.repeat(fileFields.length + 1)}files={${fileFields.map(([key], index) => `${JSON.stringify(key)}: file_${index}`).join(', ')}}, timeout=180)`) }
    else lines.push(`response = requests.${entry.method.toLowerCase()}(url, headers=headers,${body ? `\n    json=${pythonJSON(body)},` : ''} timeout=180)`)
    lines.push('response.raise_for_status()', entry.binary ? `with open(${JSON.stringify(entry.download)}, "wb") as output:\n    output.write(response.content)` : 'print(response.json())')
    return lines.join('\n')
  }
  const lines = ['const apiKey = "YOUR_API_KEY";', `const headers = { Authorization: \`Bearer ${'${apiKey}'}\`${entry.idempotent ? ', "Idempotency-Key": "my-creation-001"' : ''} };`]
  if (entry.multipart) {
    lines.push('const form = new FormData();')
    for (const [key, value] of dataFields) lines.push(`form.append(${JSON.stringify(key)}, ${JSON.stringify(typeof value === 'object' ? JSON.stringify(value) : String(value))});`)
    fileFields.forEach(([key], index) => lines.push(`form.append(${JSON.stringify(key)}, document.querySelector('input[type="file"]').files[${index}]);`))
    lines.push(`const response = await fetch(${JSON.stringify(url)}, {\n  method: ${JSON.stringify(entry.method)}, headers, body: form\n});`)
  } else {
    if (body) lines.push('headers["Content-Type"] = "application/json";')
    lines.push(`const response = await fetch(${JSON.stringify(url)}, {\n  method: ${JSON.stringify(entry.method)}, headers${body ? `,\n  body: JSON.stringify(${JSON.stringify(body, null, 2)})` : ''}\n});`)
  }
  lines.push('if (!response.ok) throw new Error(await response.text());')
  if (entry.binary) lines.push('const blob = await response.blob();', 'const url = URL.createObjectURL(blob);', 'const link = document.createElement("a");', `link.href = url; link.download = ${JSON.stringify(entry.download)};`, 'link.click(); URL.revokeObjectURL(url);')
  else lines.push('const result = await response.json();', 'console.log(result);')
  return lines.join('\n')
}
async function copy(value) { try { await navigator.clipboard.writeText(value); ElMessage.success('已复制，粘贴到你的项目吧') } catch (cause) { notifyError(cause) } }
function openGuide(which = channel.value) { fullGuideProvider.value = which; fullGuide.value = true }
const receipts = [{ status: 'generating', text: '请求已记录，等待原请求完成', tone: 'primary' }, { status: 'received', text: '上游响应已保存，可恢复下载', tone: 'primary' }, { status: 'completed', text: '媒体下载与规格校验完成', tone: 'success' }, { status: 'download_failed', text: '保留原收据，调用 download 恢复', tone: 'warning' }, { status: 'unknown', text: '接受状态待确认，查询原收据', tone: 'warning' }, { status: 'failed / no_result', text: '失败原因保留于原收据', tone: 'danger' }]
</script>

<template>
  <div class="guide-view">
    <header class="page-heading"><div><h1>好创作，也要好接入。</h1><p>从第一行请求，到完整的媒体工作流。能力、参数与示例都在这里。</p></div><div class="page-actions"><el-button :icon="Document" @click="openGuide('flow')">完整 Flow 文档</el-button><el-button :icon="Document" @click="openGuide('vids')">完整 Vids 文档</el-button></div></header>
