      <main class="guide-main surface">
        <div class="guide-topline"><el-breadcrumb separator="/"><el-breadcrumb-item>{{ channel === 'flow' ? 'Flow' : channel === 'vids' ? 'Vids' : '商务对接' }}</el-breadcrumb-item><el-breadcrumb-item>{{ current.group }}</el-breadcrumb-item></el-breadcrumb><el-button link :icon="Link" tag="a" :href="schemaURL" target="_blank">OpenAPI</el-button></div>
